export function start(port=Number(process.env.PORT||3000)){return Bun.serve({port,hostname:'0.0.0.0',async fetch(request,bunServer){return await new Promise(async(resolve,reject)=>{const parsed=new URL(request.url);const req={url:parsed.pathname+parsed.search,method:request.method,headers:Object.fromEntries(request.headers),socket:{remoteAddress:bunServer.requestIP(request)?.address||'unknown'},async *[Symbol.asyncIterator](){if(request.body)for await(const chunk of request.body)yield Buffer.from(chunk)}};let status=200,headers={};const res={writeHead(code,values){status=code;headers=values},end(value){resolve(new Response(value,{status,headers}))}};try{await handle(req,res)}catch(e){reject(e)}})}})}
if(process.env.NO_LISTEN!=='1')start();
